request.prompt:
You are operating on a local file. You may make this change yourself.

A tool is available to you:

  edit_file(path, contents)   replaces the whole file at `path` with `contents`

The file is index.html and its current contents are:

<!DOCTYPE html>
<html>
<head><title>s04</title></head>
<body>
<h2>s04</h2>
<input type="text" id="needle">
<ol id="stack">
  <li class="item">lisbon</li>
  <li class="item">lima</li>
  <li class="item">cairo</li>
  <li class="item">oslo</li>
  <li class="item">dakar</li>
</ol>
<script>
const model = { query: '' };
const field = document.getElementById('needle');
const rows = Array.from(document.querySelectorAll('#stack .item'));
function redraw() {
  model.query = field.value.toLowerCase();
  const q = model.query;
  rows.forEach(function (el) {
    const hit = el.textContent.toLowerCase().indexOf(q) !== -1;
    el.style.display = hit ? '' : 'none';
  });
}
field.addEventListener('input', redraw);
</script>
</body>
</html>


Make this change: when #clear-filter is clicked: #needle is empty; every item in the list is visible again. Ensure typing in the filter still narrows the list.
Everything the page already does must keep working.

Call the tool. Reply with exactly one call, in this form and nothing else:

edit_file("index.html", `<!DOCTYPE html>
...the complete updated page...
</html>`)

